-- ---------- counters, now that the rows are in ----------
-- ============================================================
-- Move the identity counters past the ids that were just loaded.
--
-- 02_data.sql inserts the original primary keys explicitly — order 2
-- has to stay order 2, or every screenshot and every images/<id>.jpg
-- stops matching. Postgres allows that because the columns are
-- GENERATED BY DEFAULT rather than GENERATED ALWAYS, but it does not
-- notice: each sequence is still sitting at 1.
--
-- Without this file the first customer to register would be handed
-- customer_id 1, which is already taken, and the insert would fail on
-- the primary key. Run it straight after the data load.
--
--     psql "$SUPABASE_DB_URL" -f 03_sequences.sql
--
-- products is not in the list on purpose: its ids are typed in by hand
-- so the image filenames line up, so it has no sequence to fix.
-- ============================================================

DO $$
DECLARE
  t      TEXT;
  col    TEXT;
  seq    TEXT;
  nextid BIGINT;
BEGIN
  FOR t, col IN
    SELECT c.table_name, c.column_name
    FROM information_schema.columns c
    WHERE c.table_schema = 'public'
      AND c.is_identity  = 'YES'
    ORDER BY c.table_name
  LOOP
    seq := pg_get_serial_sequence(format('public.%I', t), col);
    IF seq IS NULL THEN
      CONTINUE;
    END IF;

    -- COALESCE covers the tables the shop has never written to —
    -- cart_items, wishlist_items and login_attempts are all empty —
    -- where MAX() is NULL and the counter should simply start at 1.
    EXECUTE format('SELECT COALESCE(MAX(%I), 0) + 1 FROM public.%I', col, t) INTO nextid;
    PERFORM setval(seq, nextid, false);

    RAISE NOTICE '% .% -> next value %', t, col, nextid;
  END LOOP;
END
$$;
